//! Property and quantity set templates and the template check.
//!
//! The templates are tables generated by `cargo xtask ifc-psets` from the property and quantity
//! set definitions published by buildingSMART International for IFC2X3 TC1 and IFC4 ADD2 TC1:
//! the set name, the entities (and predefined types) it applies to, and per property its kind,
//! value type and enumeration items, or per quantity its quantity kind. IFC4X3 ADD2 publishes no
//! machine-readable definitions, so a file of that schema has no templates.
//!
//! Like the schema tables (ADR-0018), the generated files are not part of the repository until the
//! license basis is recorded: the build script enables them only when `src/schema/generated/`
//! holds both, and [`PsetTemplates::of`] returns `None` otherwise.
//!
//! [`IfcFile::check_property_sets`](crate::IfcFile::check_property_sets) compares every property
//! set and element quantity whose name starts with `Pset_` or `Qto_` with its template; see
//! [`check`].

mod check;

pub use check::{PsetCheck, PsetFinding, findings};

use std::cmp::Ordering;

use crate::model::Schema;
pub use crate::views::QuantityKind;

#[cfg(arc_ifc_pset_tables)]
mod generated {
    use super::{
        Applicable, PropertyKind, PropertyTemplate, PsetTemplates, QuantityKind, SetKind,
        SetTemplate,
    };
    include!("../schema/generated/psets_ifc2x3.rs");
    include!("../schema/generated/psets_ifc4.rs");
}

/// The templates of one schema.
#[derive(Debug)]
pub struct PsetTemplates {
    /// The schema, such as `IFC4`.
    pub schema: &'static str,
    /// The set templates by upper-case name.
    pub sets: &'static [SetTemplate],
}

/// Whether a template describes a property set or a quantity set.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SetKind {
    /// An `IfcPropertySet` (`Pset_` names).
    Properties,
    /// An `IfcElementQuantity` (`Qto_` names).
    Quantities,
}

/// A property or quantity set template.
#[derive(Debug)]
pub struct SetTemplate {
    /// The name, such as `Pset_WallCommon`.
    pub name: &'static str,
    /// Properties or quantities.
    pub kind: SetKind,
    /// The template type as published, such as `PSET_TYPEDRIVENOVERRIDE`; empty when the
    /// definition gives none.
    pub template_type: &'static str,
    /// The entities the set applies to; an occurrence of a subtype or the type object of one of
    /// them may carry it.
    pub applicable: &'static [Applicable],
    /// The properties or quantities in published order.
    pub properties: &'static [PropertyTemplate],
}

/// An entity a set applies to, optionally only with one predefined type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Applicable {
    /// The entity, such as `IfcWall`.
    pub entity: &'static str,
    /// The predefined type the set is restricted to, such as `ELECTRICACTUATOR`.
    pub predefined_type: Option<&'static str>,
}

/// A property or quantity template.
#[derive(Debug)]
pub struct PropertyTemplate {
    /// The name.
    pub name: &'static str,
    /// The kind with its value types.
    pub kind: PropertyKind,
}

/// The kind of a property template and its value types. A data type is the IFC defined type of
/// the values, such as `IfcPositiveLengthMeasure`; it is empty where the published definition
/// leaves it open.
#[derive(Debug)]
pub enum PropertyKind {
    /// `IfcPropertySingleValue`.
    Single {
        /// The value type.
        data_type: &'static str,
    },
    /// `IfcPropertyEnumeratedValue` with its `IfcPropertyEnumeration`.
    Enumerated {
        /// The enumeration name, such as `PEnum_ElementStatus`.
        enumeration: &'static str,
        /// The items in published order.
        items: &'static [&'static str],
    },
    /// `IfcPropertyBoundedValue`.
    Bounded {
        /// The type of the bounds and the set point.
        data_type: &'static str,
    },
    /// `IfcPropertyListValue`.
    List {
        /// The type of the list values.
        data_type: &'static str,
    },
    /// `IfcPropertyTableValue`.
    Table {
        /// The type of the defining values.
        defining: &'static str,
        /// The type of the defined values.
        defined: &'static str,
    },
    /// `IfcPropertyReferenceValue`.
    Reference {
        /// The entity of the referenced value, such as `IfcTimeSeries` or `IfcPerson`.
        entity: &'static str,
    },
    /// `IfcComplexProperty`.
    Complex {
        /// The `UsageName`, such as `CP_MaterialMechanicalBeam`.
        name: &'static str,
        /// The properties of the complex property.
        properties: &'static [PropertyTemplate],
    },
    /// A quantity of an `IfcElementQuantity`.
    Quantity(QuantityKind),
}

impl PropertyKind {
    /// The entity a property or quantity of this kind is written as, in upper case.
    #[must_use]
    pub fn entity(&self) -> &'static str {
        match self {
            Self::Single { .. } => "IFCPROPERTYSINGLEVALUE",
            Self::Enumerated { .. } => "IFCPROPERTYENUMERATEDVALUE",
            Self::Bounded { .. } => "IFCPROPERTYBOUNDEDVALUE",
            Self::List { .. } => "IFCPROPERTYLISTVALUE",
            Self::Table { .. } => "IFCPROPERTYTABLEVALUE",
            Self::Reference { .. } => "IFCPROPERTYREFERENCEVALUE",
            Self::Complex { .. } => "IFCCOMPLEXPROPERTY",
            Self::Quantity(kind) => match kind {
                QuantityKind::Length => "IFCQUANTITYLENGTH",
                QuantityKind::Area => "IFCQUANTITYAREA",
                QuantityKind::Volume => "IFCQUANTITYVOLUME",
                QuantityKind::Count => "IFCQUANTITYCOUNT",
                QuantityKind::Weight => "IFCQUANTITYWEIGHT",
                QuantityKind::Time => "IFCQUANTITYTIME",
            },
        }
    }
}

fn compare_upper(a: &str, b: &str) -> Ordering {
    a.bytes()
        .map(|c| c.to_ascii_uppercase())
        .cmp(b.bytes().map(|c| c.to_ascii_uppercase()))
}

impl PsetTemplates {
    /// The templates of `schema`, or `None` for IFC4X3, another schema or a build without the
    /// generated templates.
    #[must_use]
    pub fn of(schema: &Schema) -> Option<&'static Self> {
        #[cfg(arc_ifc_pset_tables)]
        {
            match schema {
                Schema::Ifc2x3 => Some(&generated::IFC2X3),
                Schema::Ifc4 => Some(&generated::IFC4),
                Schema::Ifc4x3 | Schema::Other(_) => None,
            }
        }
        #[cfg(not(arc_ifc_pset_tables))]
        {
            let _ = schema;
            None
        }
    }

    /// The template named `name`, ignoring ASCII case.
    #[must_use]
    pub fn get(&self, name: &str) -> Option<&'static SetTemplate> {
        self.sets
            .binary_search_by(|s| compare_upper(s.name, name))
            .ok()
            .and_then(|i| self.sets.get(i))
    }
}

impl SetTemplate {
    /// The property or quantity named `name` (names are case-sensitive in IFC).
    #[must_use]
    pub fn property(&self, name: &str) -> Option<&'static PropertyTemplate> {
        self.properties.iter().find(|p| p.name == name)
    }
}

